def interval_gaps(intervals, start, end):
    # Filter intervals to only those within [start, end)
    filtered = []
    for a, b in intervals:
        # Clip interval to [start, end)
        a_clipped = max(a, start)
        b_clipped = min(b, end)
        if a_clipped < b_clipped:
            filtered.append((a_clipped, b_clipped))

    # Sort intervals by start time
    filtered.sort()

    # Merge overlapping intervals
    merged = []
    for interval in filtered:
        if not merged or interval[0] > merged[-1][1]:
            merged.append(interval)
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    # Find gaps
    gaps = []
    current = start
    for a, b in merged:
        if current < a:
            gaps.append([current, a])
        current = max(current, b)

    if current < end:
        gaps.append([current, end])

    return gaps
